			scope := f.writeScope()
			scope.Permissions = permissions
			forged := forgeScoped(t, f.bot.Id, scope)
			forged.Roles = f.bot.Roles
			rctx := th.Context.WithSession(forged)

			canRead, _ := th.App.SessionHasPermissionToChannel(rctx, *forged, f.writePrivate.Id, model.PermissionReadChannelContent)
			require.False(t, canRead, "precondition: scope permissions=%v must not read channel %s", permissions, f.writePrivate.Id)

			for _, permission := range []*model.Permission{
				model.PermissionAddReaction,
				model.PermissionAddBookmarkPrivateChannel,
				model.PermissionEditBookmarkPrivateChannel,
				model.PermissionOrderBookmarkPrivateChannel,
			} {
				scoped, allowed := th.App.EvaluateSessionScope(rctx, forged, permission.Id, SessionScopeTarget{ChannelID: f.writePrivate.Id})
