func TestHuntD_SessionScopeParse(t *testing.T) {
	inputs, pool := huntDScopeInputs()
	allPerms := append(append([]string{}, huntDReadPerms...), huntDWritePerms...)
	allPerms = append(allPerms, "create_post")
	for i, raw := range inputs {
		huntDRecord("TestHuntD_SessionScopeParse", i, raw, func() any {
			sess := &Session{Props: StringMap{SessionPropScope: raw}}
			scope, scoped := sess.Scope()
			b, err := json.Marshal(scope)
			has := map[string]bool{}
			for _, p := range allPerms {
				has[p] = scope.HasPermission(p)
			}
			lists := map[string]bool{}
			for _, id := range pool {
				lists[id] = scope.ListsChannel(id)
			}
			return map[string]any{"scoped": scoped, "is_scoped": sess.IsScoped(), "scope": string(b), "marshal_err": huntDErr(err), "has": has, "lists": lists}
		})
	}
}

